#!/usr/bin/env bash
# Tadpole pilot driver for one sample: can the Tringe-lab (iii) assembly contiguity be regenerated by BBTools read
# preparation (BBDuk -> BBMerge with Tadpole extension -> Tadpole correction) ahead of metaSPAdes 3.15.3?
#
#   Arm A  merge + Tadpole : BBDuk -> bbmerge-auto rem k=62 extend2=50 ecct -> Tadpole mode=correct (merged + unmerged)
#                            -> BBDuk qtrim=r trimq=10 on the unmerged pairs -> metaSPAdes --meta (-1/-2 unmerged, --merged merged)
#   Arm B  Tadpole only    : BBDuk -> Tadpole mode=correct (pairs) -> BBDuk qtrim=r trimq=10 -> metaSPAdes --meta (-1/-2)
#   Arm C  (optional)      : Arm A reads -> spades.py in default (multicell) mode, started when Arm A's assembly ends
#
# Arms A and B share the BBDuk output, the Tadpole settings and every SPAdes flag except --merged, so A vs B isolates
# the merging. Both use --only-assembler (Tadpole replaces BayesHammer), so A/B differ from the 2026 KBase run in read
# preparation AND corrector; see README.md.
#
# Usage (on poplar):  nohup setsid bash run_sample.sh <sample> <run> [armC] > <outdir>/<sample>/driver.log 2>&1 < /dev/null &
# Environment overrides (used by the smoke test): READS_DIR OUT_DIR TPRE TASM XMX_BIG XMX_SMALL SPADES_MEM KLIST NOWAIT
# Resumable: each finished step leaves <outdir>/<sample>/.done/<step>; re-running skips finished steps.
set -euo pipefail
SAMPLE=${1:?sample}; RUN=${2:?SRA run}; ARMC=${3:-}
ROOT=/scratch1/afreiburger/salterns_2026/tadpole_pilot
READS_DIR=${READS_DIR:-$ROOT/reads}
OUT_DIR=${OUT_DIR:-$ROOT}
TPRE=${TPRE:-24}            # threads for preprocessing (one step at a time per sample)
TASM=${TASM:-12}            # threads per SPAdes run (Arm A and Arm B run side by side -> 24 per sample)
XMX_BIG=${XMX_BIG:-200g}    # BBMerge-with-Tadpole and Tadpole k-mer tables (k=62, prefilter=2)
XMX_SMALL=${XMX_SMALL:-16g} # BBDuk
SPADES_MEM=${SPADES_MEM:-400}
KLIST=${KLIST:-33,55,77,99,127}
BB=/scratch1/afreiburger/emilykin/processed/reanalysis_norm/env_bbtools/bin   # BBTools 39.81 (openjdk 25)
SP=/scratch1/afreiburger/salterns_2026/envs/spades3153/bin                     # SPAdes 3.15.3 (python 3.9)
export PATH=$SP:$BB:$PATH

D=$OUT_DIR/$SAMPLE
mkdir -p "$D"/{qc,armA,armB,logs,.done}
[ -n "$ARMC" ] && mkdir -p "$D/armC"
echo $$ > "$D/driver.pid"
ts() { date +%F' '%T; }
step() {  # step <name> <command...>; logs to logs/<name>.log, marker .done/<name>
  local name=$1; shift
  if [ -e "$D/.done/$name" ]; then echo "[$(ts)] skip $name (done)"; return 0; fi
  echo "[$(ts)] start $name"; echo "$name" > "$D/STATUS"
  if "$@" > "$D/logs/$name.log" 2>&1; then touch "$D/.done/$name"; echo "[$(ts)] done  $name"
  else echo "[$(ts)] FAILED $name (see logs/$name.log)"; echo "FAILED $name" > "$D/STATUS"; return 1; fi
}

R1=$READS_DIR/${RUN}_1.fastq; R2=$READS_DIR/${RUN}_2.fastq
# 0. wait for the verified download
if [ -z "${NOWAIT:-}" ]; then
  echo "[$(ts)] waiting for $READS_DIR/$RUN.ok"; echo "waiting_for_reads" > "$D/STATUS"
  while [ ! -e "$READS_DIR/$RUN.ok" ]; do
    [ -e "$READS_DIR/$RUN.FAIL" ] && { echo "download FAILED for $RUN"; echo "FAILED download" > "$D/STATUS"; exit 1; }
    sleep 60
  done
fi
# 0b. fasterq-dump writes "+SRR... 1 length=151" separator lines; the multithreaded FASTQ reader in BBTools 39.81
#     asserts a bare "+" (stream/FASTQ.java quadToReadVec: plus.length==1) and its worker threads die. Rewrite the
#     separator lines in place, once per run (sequences and qualities untouched, so the download checks still hold).
fix_plus() {
  local f
  for f in "$R1" "$R2"; do
    nice -n 10 awk 'NR%4==3{print "+"; next} {print}' "$f" > "$f.plusfix.tmp"
    [ "$(stat -c %s "$f.plusfix.tmp")" -lt "$(stat -c %s "$f")" ] && mv "$f.plusfix.tmp" "$f"
  done
  nice -n 10 awk 'NR%4==3 && $0!="+"{bad++} END{print "non-bare plus lines left in R1:", bad+0; exit (bad>0)}' "$R1"
  touch "$READS_DIR/$RUN.plusfixed"
}
if [ ! -e "$READS_DIR/$RUN.plusfixed" ]; then step fix_plus_$RUN fix_plus; fi

# 1. BBDuk, rqcfilter2 defaults (BBTools 39.81 help) minus human/microbe removal, clumpify and sketch:
#    adapter trim trimk=23 mink=11 hdist=1 tpe tbo ftm=5, no quality trimming (qtrim=f), maq=5 minlen=45 mlf=0.333 maxns=0
step bbduk_adapt nice -n 10 bbduk.sh -Xmx$XMX_SMALL t=$TPRE in1=$R1 in2=$R2 \
  out1=$D/qc/trim_1.fq.gz out2=$D/qc/trim_2.fq.gz ref=adapters ktrim=r k=23 mink=11 hdist=1 tpe tbo ftm=5 \
  maq=5 minlen=45 mlf=0.333 maxns=0 ordered stats=$D/qc/adapt_stats.txt
#    then artifact + phiX removal, filterk=31 hdist=1
step bbduk_filter nice -n 10 bbduk.sh -Xmx$XMX_SMALL t=$TPRE in1=$D/qc/trim_1.fq.gz in2=$D/qc/trim_2.fq.gz \
  out1=$D/qc/clean_1.fq.gz out2=$D/qc/clean_2.fq.gz ref=artifacts,phix k=31 hdist=1 ordered stats=$D/qc/filter_stats.txt

# 2. Arm A read preparation (TPRE threads, serial)
A=$D/armA
step A1_bbmerge nice -n 10 bbmerge-auto.sh -Xmx$XMX_BIG t=$TPRE in1=$D/qc/clean_1.fq.gz in2=$D/qc/clean_2.fq.gz \
  out=$A/merged.fq.gz outu1=$A/unmerged_1.fq.gz outu2=$A/unmerged_2.fq.gz rem k=62 extend2=50 ecct prefilter=2 \
  ihist=$A/ihist.txt ordered
# Tadpole on merged + unmerged: the documented one-call form (in=u1,merged in2=u2,null) fails in 39.81
# ("Can't read file 'null'"), so two passes; each builds its k-mer table from ALL reads (in/in2 + extra).
step A2a_tadpole_pairs nice -n 10 tadpole.sh -Xmx$XMX_BIG t=$TPRE mode=correct k=62 prefilter=2 \
  in=$A/unmerged_1.fq.gz in2=$A/unmerged_2.fq.gz extra=$A/merged.fq.gz \
  out=$A/ecc_u_1.fq.gz out2=$A/ecc_u_2.fq.gz ordered
step A2b_tadpole_merged nice -n 10 tadpole.sh -Xmx$XMX_BIG t=$TPRE mode=correct k=62 prefilter=2 \
  in=$A/merged.fq.gz extra=$A/unmerged_1.fq.gz,$A/unmerged_2.fq.gz out=$A/ecc_merged.fq.gz ordered
step A3_qtrim nice -n 10 bbduk.sh -Xmx$XMX_SMALL t=$TPRE in1=$A/ecc_u_1.fq.gz in2=$A/ecc_u_2.fq.gz \
  out1=$A/reads_1.fq.gz out2=$A/reads_2.fq.gz qtrim=r trimq=10 minlen=45 ordered

SPADES_COMMON="--only-assembler -k $KLIST -t $TASM -m $SPADES_MEM --phred-offset 33"
run_spades_A() { step A4_metaspades nice -n 10 spades.py --meta $SPADES_COMMON \
  -1 $A/reads_1.fq.gz -2 $A/reads_2.fq.gz --merged $A/ecc_merged.fq.gz -o $A/spades; }
run_spades_C() { step C1_spades_default nice -n 10 spades.py $SPADES_COMMON \
  -1 $A/reads_1.fq.gz -2 $A/reads_2.fq.gz --merged $A/ecc_merged.fq.gz -o $D/armC/spades; }
# Arm A assembly in the background (TASM threads); Arm C, if asked for, follows it in the same slot
( run_spades_A && { [ -z "$ARMC" ] || run_spades_C; } ) > "$D/logs/armA_chain.out" 2>&1 &
PID_A=$!; echo $PID_A > "$D/armA_chain.pid"
echo "[$(ts)] Arm A chain (metaSPAdes${ARMC:+, then Arm C}) PID $PID_A"

# 3. Arm B read preparation (TPRE - TASM threads while Arm A assembles), then its assembly
TB=$(( TPRE - TASM )); [ $TB -lt 1 ] && TB=1
B=$D/armB
step B1_tadpole nice -n 10 tadpole.sh -Xmx$XMX_BIG t=$TB mode=correct k=62 prefilter=2 \
  in=$D/qc/clean_1.fq.gz in2=$D/qc/clean_2.fq.gz out=$B/ecc_1.fq.gz out2=$B/ecc_2.fq.gz ordered
step B2_qtrim nice -n 10 bbduk.sh -Xmx$XMX_SMALL t=$TB in1=$B/ecc_1.fq.gz in2=$B/ecc_2.fq.gz \
  out1=$B/reads_1.fq.gz out2=$B/reads_2.fq.gz qtrim=r trimq=10 minlen=45 ordered
step B3_metaspades nice -n 10 spades.py --meta $SPADES_COMMON -1 $B/reads_1.fq.gz -2 $B/reads_2.fq.gz -o $B/spades

echo "waiting_for_armA_chain" > "$D/STATUS"
wait $PID_A || { echo "[$(ts)] Arm A chain FAILED (logs/armA_chain.out)"; echo "FAILED armA_chain" > "$D/STATUS"; exit 1; }
echo "ALL_DONE" > "$D/STATUS"; touch "$D/.done/ALL"
echo "[$(ts)] all steps done for $SAMPLE"
